def solution(n):
    """
    Generates an array of strings from 1 to n following FizzBuzz rules.

    Args:
    n (int): The upper limit of the range (inclusive).

    Returns:
    list: A list of strings adhering to FizzBuzz rules.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

