def solution(s):
    """
    Count the number of unique characters in a string, where a unique character appears exactly once.

    Args:
    s (str): The input string consisting of lowercase and uppercase English letters.

    Returns:
    int: The count of unique characters in the string.
    """
    # Initialize a dictionary to store the frequency of each character
    char_count = {}

    # Iterate through each character in the string and update the frequency count
    for char in s:
        if char in char_count:
            char_count[char] += 1
        else:
            char_count[char] = 1

    # Count the number of characters that appear exactly once
    unique_count = 0
    for count in char_count.values():
        if count == 1:
            unique_count += 1

    return unique_count

