class TestFindFirstOccurrence(unittest.TestCase):
    def test_basic_occurrence(self):
        """Test basic case where target appears once in the array."""
        self.assertEqual(solution([1, 2, 3, 4, 5], 3), 2)

    def test_multiple_occurrences(self):
        """Test case where target appears multiple times, should return first occurrence."""
        self.assertEqual(solution([5, 7, 7, 8, 8, 10], 8), 3)

    def test_target_not_found(self):
        """Test case where target is not present in the array."""
        self.assertEqual(solution([1, 3, 5, 7, 9], 4), -1)

    def test_first_element(self):
        """Test case where target is the first element of the array."""
        self.assertEqual(solution([10, 20, 30, 40, 50], 10), 0)

    def test_last_element(self):
        """Test case where target is the last element of the array."""
        self.assertEqual(solution([10, 20, 30, 40, 50], 50), 4)

    def test_single_element_match(self):
        """Test case with single-element array that matches target."""
        self.assertEqual(solution([42], 42), 0)

    def test_single_element_no_match(self):
        """Test case with single-element array that doesn't match target."""
        self.assertEqual(solution([42], 99), -1)

    def test_empty_array(self):
        """Test case with empty array (should always return -1)."""
        self.assertEqual(solution([], 5), -1)

    def test_negative_numbers(self):
        """Test case with negative numbers in array and negative target."""
        self.assertEqual(solution([-10, -5, 0, 5, 10], -5), 1)

    def test_extreme_values(self):
        """Test case with extreme integer values (boundary values)."""
        self.assertEqual(solution([-10**9, 0, 10**9], 10**9), 2)

    def test_all_same_elements(self):
        """Test case where all elements are the same and match target."""
        self.assertEqual(solution([7, 7, 7, 7, 7], 7), 0)

    def test_large_array(self):
        """Test case with large array (stress test)."""
        nums = [i for i in range(1, 10001)] + [42]  # target at last position
        self.assertEqual(solution(nums, 42), 10000)

    def test_target_at_middle(self):
        """Test case where target is exactly in the middle of the array."""
        nums = list(range(1, 100, 2))  # Odd length array
        self.assertEqual(solution(nums, 51), 25)

    def test_duplicates_before_target(self):
        """Test case with duplicates appearing before the target."""
        nums = [1, 1, 1, 1, 2, 2, 2, 3, 3, 3]
        self.assertEqual(solution(nums, 3), 7)

    def test_very_large_target(self):
        """Test case with very large target value."""
        nums = [10**9 - 1, 10**9, 10**9 + 1]
        self.assertEqual(solution(nums, 10**9 + 1), 2)

    def test_very_small_target(self):
        """Test case with very small target value."""
        nums = [-10**9 - 1, -10**9, -10**9 + 1]
        self.assertEqual(solution(nums, -10**9 - 1), 0)

