def solution(n):
    """
    Generate a list of strings from 1 to n with replacements:
    - "Fizz" for multiples of 3
    - "Buzz" for multiples of 5
    - "FizzBuzz" for multiples of both 3 and 5
    """
    result = []
    for i in range(1, n+1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def solution(age):
    """
    Validates the given age and returns an appropriate message based on its validity.

    Args:
    age (int): The age to be validated.

    Returns:
    str: A message indicating whether the age is valid or an error message if it's invalid.
    """
    if not isinstance(age, int):
        return "Invalid age: Age must be an integer."
    if age < 0:
        return "Invalid age: Age cannot be negative."
    elif age > 120:
        return "Invalid age: Age cannot exceed 120."
    else:
        return "Valid age."

