def solution(nums, target):
    """
    Search for a target in a rotated sorted array using a modified binary search.

    Args:
    nums (List[int]): A rotated sorted array of unique integers.
    target (int): The integer to search for in the array.

    Returns:
    int: The index of the target in the array, or -1 if not found.
    """
    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            return mid

        # Check if the left half is sorted
        if nums[left] <= nums[mid]:
            # Target is in the left sorted half
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            # Right half is sorted
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1

    return -1
