def solution(text, target):
    """
    Recursively checks if the target character exists in the given text.
    Uses a helper function to avoid recursion limit issues.

    Args:
        text (str): The string to search within.
        target (str): The character to search for (must be lowercase letter).

    Returns:
        bool: True if the target is found, False otherwise.
    """
    def recursive_search(s):
        if not s:
            return False
        if s[0] == target:
            return True
        return recursive_search(s[1:])

