def solution(nums):
    if not nums:
        return 0

    n = len(nums)
    # Initialize a dp array where dp[i] represents the length of the longest increasing subsequence ending at nums[i]
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                # If nums[i] can extend the subsequence ending at nums[j], update dp[i]
                dp[i] = max(dp[i], dp[j] + 1)

    # The answer is the maximum value in the dp array
    return max(dp)

