def solution(operations):
    accounts = {}
    results = []
    for operation in operations:
        parts = operation.split()
        op_type = parts[0]

        if op_type == "CREATE":
            account_id = parts[1]
            initial_balance = int(parts[2])
            if initial_balance >= 0:
                if account_id not in accounts:
                    accounts[account_id] = initial_balance
                    results.append("Account created")
                else:
                    results.append("Account already exists")
            else:
                results.append("Initial balance cannot be negative")

        elif op_type == "DEPOSIT":
            account_id = parts[1]
            amount = int(parts[2])
            if account_id in accounts:
                if amount > 0:
                    accounts[account_id] += amount
                    results.append("Deposit successful")
                else:
                    results.append("Deposit amount must be positive")
            else:
                results.append("Account not found")

        elif op_type == "WITHDRAW":
            account_id = parts[1]
            amount = int(parts[2])
            if account_id in accounts:
                if amount > 0:
                    if accounts[account_id] >= amount:
                        accounts[account_id] -= amount
                        results.append("Withdrawal successful")
                    else:
                        results.append("Insufficient funds")
                else:
                    results.append("Withdrawal amount must be positive")
            else:
                results.append("Account not found")

        elif op_type == "BALANCE":
            account_id = parts[1]
            if account_id in accounts:
                results.append(f"Balance: {accounts[account_id]}")
            else:
                results.append("Account not found")

    return results

