            account_id = parts[1]
            initial_balance = int(parts[2])
            if initial_balance >= 0:
                if account_id not in accounts:
                    accounts[account_id] = initial_balance
                    results.append("Account created")
                else:
                    results.append("Account already exists")
            else:
                results.append("Invalid initial balance")

        elif op_type == "DEPOSIT":
            account_id = parts[1]
            amount = int(parts[2])
            if account_id in accounts:
                if amount > 0:
                    accounts[account_id] += amount
                    results.append("Deposit successful")
                else:
                    results.append("Invalid deposit amount")
            else:
                results.append("Account not found")

        elif op_type == "WITHDRAW":
            account_id = parts[1]
            amount = int(parts[2])
            if account_id in accounts:
                if amount > 0:
                    if accounts[account_id] >= amount:
                        accounts[account_id] -= amount
                        results.append("Withdrawal successful")
                    else:
                        results.append("Insufficient funds")
                else:
                    results.append("Invalid withdrawal amount")
            else:
                results.append("Account not found")

        elif op_type == "BALANCE":
            account_id = parts[1]
            if account_id in accounts:
                results.append(f"Balance: {accounts[account_id]}")
            else:
                results.append("Account not found")

    return results

def solution(username):
    # Check if the username length is between 5 and 20 characters
    if len(username) < 5 or len(username) > 20:
        return (False, "Username must be between 5 and 20 characters long.")

    # Check if the username starts with a digit
    if username[0].isdigit():
        return (False, "Username cannot start with a digit.")

    # Check if the username contains only allowed characters
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
    for char in username:
        if char not in allowed_chars:
            return (False, "Username can only contain alphanumeric characters, underscores, and hyphens.")

    # If all checks pass, return True with an empty error message
    return (True, "")

