    if len(nums) == 1:
        return max(0, nums[0])

    # Initialize variables to track the maximum sums
    prev2 = 0  # Max sum two houses back
    prev1 = max(0, nums[0])  # Max sum one house back (or 0 if negative)

    for i in range(1, len(nums)):
        current = max(prev1, prev2 + nums[i], 0)  # Ensure current sum is >=0
        prev2, prev1 = prev1, current

    return max(prev1, 0)  # Ensure final result is >=0

