    prev2 = float('-inf')  # Max sum two houses back
    prev1 = nums[0]  # Max sum one house back

    for i in range(1, len(nums)):
        current = max(prev1, prev2 + nums[i], nums[i])  # Ensure current sum considers single element
        prev2, prev1 = prev1, current

    return max(prev1, prev2)  # Ensure final result is the maximum possible sum

def solution(nums):
    if not nums:
        return 0
    if len(nums) == 1:
        return max(nums[0], 0)  # Ensure non-negative

    # Initialize variables to track the maximum sums
    prev2 = 0  # Max sum two houses back, start with 0 to skip negative values
    prev1 = max(nums[0], 0)  # Max sum one house back, ensure non-negative

    for i in range(1, len(nums)):
        current = max(prev1, prev2 + max(nums[i], 0))  # Consider only non-negative contributions
        prev2, prev1 = prev1, current

    return max(prev1, prev2)  # Ensure final result is the maximum possible sum

