def solution(coins, amount):
    # Initialize a DP array where dp[i] will store the number of ways to make amount i
    dp = [0] * (amount + 1)
    dp[0] = 1  # Base case: one way to make amount 0 (use no coins)

    for coin in coins:
        for i in range(coin, amount + 1):
            dp[i] += dp[i - coin]

    return dp[amount]

