def solution(m, n):
    # Initialize a DP table with dimensions m x n, filled with 1s
    dp = [[1 for _ in range(n)] for _ in range(m)]

    # Populate the DP table
    for i in range(1, m):
        for j in range(1, n):
            dp[i][j] = dp[i-1][j] + dp[i][j-1]

    return dp[m-1][n-1]

