def solution(nums):
    from collections import defaultdict

    if not nums:
        return []

    freq = defaultdict(int)
    for num in nums:
        freq[num] += 1

    unique_nums = list(freq.keys())

    def recursive_sort(arr):
        if len(arr) <= 1:
            return arr
        pivot = arr[0]
        left = []
        right = []
        for x in arr[1:]:
            if freq[x] > freq[pivot]:
                left.append(x)
            elif freq[x] < freq[pivot]:
                right.append(x)
            else:
                if x < pivot:
                    left.append(x)
                else:
                    right.append(x)
        return recursive_sort(left) + [pivot] + recursive_sort(right)

    sorted_unique = recursive_sort(unique_nums)

    result = []
    for num in sorted_unique:
        result.extend([num] * freq[num])

    return result

def solution(nums, target):
    """
    Searches for the target value in a rotated sorted array and returns its index.
    Handles empty arrays and non-integer values by returning -1 or raising ValueError.

    Args:
        nums: List of integers (or mixed types for error checking)
        target: Integer to search for in the array

    Returns:
        Integer index of the target if found, -1 otherwise. Raises ValueError for invalid inputs.
    """
    try:
        if not all(isinstance(num, int) for num in nums):
            raise ValueError("Input array contains non-integer values.")
    except TypeError:
        # Handle case where nums is not iterable (like None, but per problem statement, nums is an array)
        raise ValueError("Input must be a list of integers.")

    if len(nums) == 0:
        return -1

    left, right = 0, len(nums) - 1

    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            return mid

        # Check if the left side is sorted
        if nums[left] <= nums[mid]:
            if nums[left] <= target < nums[mid]:
                right = mid - 1
            else:
                left = mid + 1
        else:
            if nums[mid] < target <= nums[right]:
                left = mid + 1
            else:
                right = mid - 1
    return -1

