def solution(nums):
    """
    This function takes a list of integers and returns a new list containing only the unique elements,
    maintaining the original order of their first appearance.

    Args:
        nums: A list of integers.

    Returns:
        A list of integers containing only the unique elements from the input list.
    """
    # Use a dictionary to keep track of the count of each element
    count_dict = {}

    # First pass: count the occurrences of each element
    for num in nums:
        if num in count_dict:
            count_dict[num] += 1
        else:
            count_dict[num] = 1

    # Second pass: collect elements that appear exactly once, maintaining order
    unique_elements = []
    for num in nums:
        if count_dict[num] == 1:
            unique_elements.append(num)

    return unique_elements

