def solution(grid):
    m = len(grid)
    n = len(grid[0]) if m > 0 else 0

    # Create a DP table initialized to 0
    dp = [[0 for _ in range(n)] for _ in range(m)]

    # Initialize the starting point
    dp[0][0] = 1 if grid[0][0] == 0 else 0

    # Fill the first row: can only reach from the left
    for j in range(1, n):
        if grid[0][j] == 0:
            dp[0][j] = dp[0][j-1]
        else:
            dp[0][j] = 0

    # Fill the first column: can only reach from the top
    for i in range(1, m):
        if grid[i][0] == 0:
            dp[i][0] = dp[i-1][0]
        else:
            dp[i][0] = 0

    # Fill the rest of the table
    for i in range(1, m):
        for j in range(1, n):
            if grid[i][j] == 0:
                dp[i][j] = dp[i-1][j] + dp[i][j-1]
            else:
                dp[i][j] = 0

    return dp[m-1][n-1]

