def solution(nums):
    if not nums:
        return (0, 0)

    n = len(nums)
    # Initialize dp array where dp[i] represents the length of the LIS ending at index i
    dp = [1] * n

    # Compute the dp array
    for i in range(1, n):
        for j in range(i):
            if nums[i] > nums[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    # The length of the LIS is the maximum value in dp
    lis_length = max(dp)

    # The minimum deletions is the total elements minus the LIS length
    min_deletions = n - lis_length

    return (lis_length, min_deletions)

