    sub = []
    for num in nums:
        left, right = 0, len(sub)
        while left < right:
            mid = (left + right) // 2
            if sub[mid] < num:
                left = mid + 1
            else:
                right = mid
        if left == len(sub):
            sub.append(num)
        else:
            sub[left] = num
    lis_length = len(sub)

    # Now find how many elements are part of at least one LIS
    # We'll use Patience Sort-like approach to track these elements
    tails = []
    # For each element, store the length of the LIS ending at that position
    lis_at = [0] * len(nums)

    for i, num in enumerate(nums):
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid
        if left == len(tails):
            tails.append(num)
        else:
            tails[left] = num
        lis_at[i] = left + 1  # LIS length ending at position i

    # Now count how many elements have LIS length equal to the global LIS length
    # or are part of any LIS sequence
    count = 0
    remaining = lis_length
    # We'll count backwards to identify the elements that form the LIS
    for i in range(len(nums)-1, -1, -1):
        if lis_at[i] == remaining:
            count += 1
            remaining -= 1

    # The minimum deletions is total length minus count
    min_deletions = len(nums) - count

    return (lis_length, min_deletions)

