    If an error code (-1, -2, -3) is encountered during the search,
    immediately return the corresponding error message.
    Otherwise, return the index of the target if found, or -1 if not found.
    """
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        # Check for error codes
        if arr[mid] == -1:
            return "Data corrupted"
        elif arr[mid] == -2:
            return "Search timeout"
        elif arr[mid] == -3:
            return "Invalid input"

        # Proceed with binary search
        if arr[mid] == target:
