def solution(arr, target):
    """
    Perform a binary search on a sorted array that may contain error codes.
    Returns:
    - Error message if any error code (-1, -2, -3) is encountered during search
    - Index of target if found (even if target is an error code)
    - -1 if target not found and no error codes encountered
    """
    # First scan the array for any error codes
    for num in arr:
        if num == -1:
            return "Data corrupted"
        if num == -2:
            return "Search timeout"
        if num == -3:
            return "Invalid input"

    # If no error codes found, proceed with binary search
    left, right = 0, len(arr) - 1

    while left <= right:
        mid = (left + right) // 2

        if arr[mid] == target:
            return mid

        if arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return -1

